const toggle = document.querySelector('.menu-toggle');
const navigation = document.querySelector('#navigation');
function closeMenu(){toggle?.setAttribute('aria-expanded','false');navigation?.classList.remove('open');toggle?.setAttribute('aria-label','Open navigation');}
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');navigation.classList.toggle('open',open);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const wasOpen=toggle?.getAttribute('aria-expanded')==='true';closeMenu();if(wasOpen)toggle.focus();}});
document.addEventListener('click',e=>{if(!e.target.closest('.nav'))closeMenu();});
window.addEventListener('resize',()=>{if(innerWidth>780)closeMenu();});
window.addEventListener('scroll',()=>document.querySelector('.header').classList.toggle('scrolled',scrollY>10),{passive:true});
document.querySelectorAll('.faqs details').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)document.querySelectorAll('.faqs details').forEach(other=>{if(other!==item)other.open=false;});}));
const form=document.querySelector('#appointment');
if(form){const date=form.elements.date;const today=new Date();date.min=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;const service=new URLSearchParams(location.search).get('service');if(service&&[...form.elements.service.options].some(o=>o.value===service))form.elements.service.value=service;form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const text=`Hello Cosmopolitan Dental Care,\nI’d like to enquire about an appointment.\n\nName: ${data.get('name').trim()}\nPreferred contact: ${data.get('contact').trim()}\nTreatment: ${data.get('service')}\nPreferred date: ${data.get('date')}\nPreferred time: ${data.get('time')}${data.get('message').trim()?'\nMessage: '+data.get('message').trim():''}\n\nPlease let me know your availability. Thank you!`;document.querySelector('#enquiry-text').textContent=text;const result=document.querySelector('#enquiry-result');result.hidden=false;result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});});document.querySelector('#copy-enquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#enquiry-text').textContent);document.querySelector('#copy-status').textContent='Copied. You can now paste your enquiry into an Instagram message.';}catch{document.querySelector('#copy-status').textContent='Please select and copy the enquiry text above.';}});}
